import React, { useState } from 'react';
import { Database } from 'lucide-react';
import { parseMoney } from '../utils';

const MachineLogger = ({ onSubmit, onCancel }) => {
    const [type, setType] = useState('Phoenix Link'); const [form, setForm] = useState({});
    const handleSubmit = (e) => { e.preventDefault(); let unitWin = 0; const mIn = parseMoney(form.moneyIn); const mOut = parseMoney(form.moneyOut); const bet = parseMoney(form.bet) || 1; unitWin = (mOut - mIn) / (bet === 0 ? 1 : bet); let extraData = {}; if(type === 'World Cruise') extraData.count = (parseInt(form.red)||0) + (parseInt(form.purple)||0) + (parseInt(form.green)||0); onSubmit({ ...form, ...extraData, machineType: type, unitWin }); };
    return (
        <div className="bg-gray-800 p-6 rounded-xl border border-gray-700"><h2 className="text-xl font-bold mb-6 flex items-center gap-2"><Database className="text-purple-400" /> Log Machine Data</h2><div className="flex gap-2 mb-4 overflow-x-auto pb-2">{['Phoenix Link', 'World Cruise', 'What the Duck', 'Temple Falls'].map(m => (<button key={m} onClick={() => setType(m)} className={`px-3 py-1 rounded whitespace-nowrap text-sm font-bold ${type === m ? 'bg-purple-600 text-white' : 'bg-gray-700 text-gray-300'}`}>{m}</button>))}</div><form onSubmit={handleSubmit} className="space-y-4"><div><label className="block text-xs text-gray-400">Location</label><input className="w-full bg-gray-900 border border-gray-600 rounded p-2 text-white" required onChange={e => setForm({...form, location: e.target.value})} /></div><div className="grid grid-cols-2 gap-4"><div><label className="block text-xs text-gray-400">Bet ($)</label><input type="number" step="0.01" className="w-full bg-gray-900 border border-gray-600 rounded p-2 text-white" required onChange={e => setForm({...form, bet: e.target.value})} /></div>{type !== 'Temple Falls' && <div><label className="block text-xs text-gray-400">Denom</label><select className="w-full bg-gray-900 border border-gray-600 rounded p-2 text-white" onChange={e => setForm({...form, denom: e.target.value})}><option>1c</option><option>2c</option><option>5c</option><option>10c</option><option>$1</option></select></div>}</div>{type === 'Phoenix Link' && (<div><label className="block text-xs text-gray-400">Starting Number</label><input type="number" className="w-full bg-gray-900 border border-gray-600 rounded p-2 text-white" onChange={e => setForm({...form, startingNum: e.target.value})} /></div>)}{type === 'World Cruise' && (<div className="grid grid-cols-3 gap-2"><div><label className="text-xs text-red-400">Red</label><input type="number" className="w-full bg-gray-900 border border-gray-600 rounded p-2 text-white" onChange={e => setForm({...form, red: e.target.value})} /></div><div><label className="text-xs text-purple-400">Purple</label><input type="number" className="w-full bg-gray-900 border border-gray-600 rounded p-2 text-white" onChange={e => setForm({...form, purple: e.target.value})} /></div><div><label className="text-xs text-green-400">Green</label><input type="number" className="w-full bg-gray-900 border border-gray-600 rounded p-2 text-white" onChange={e => setForm({...form, green: e.target.value})} /></div></div>)}{type === 'What the Duck' && (<div className="grid grid-cols-2 gap-4"><div><label className="text-xs text-gray-400">Explodes</label><input type="number" className="w-full bg-gray-900 border border-gray-600 rounded p-2 text-white" onChange={e => setForm({...form, explodes: e.target.value})} /></div><div><label className="text-xs text-gray-400">Bounties</label><input type="number" className="w-full bg-gray-900 border border-gray-600 rounded p-2 text-white" onChange={e => setForm({...form, bounties: e.target.value})} /></div></div>)}{type === 'Temple Falls' && (<div><label className="block text-xs text-gray-400">Count (e.g. 450B)</label><input className="w-full bg-gray-900 border border-gray-600 rounded p-2 text-white" onChange={e => setForm({...form, count: e.target.value})} /></div>)}<div className="grid grid-cols-2 gap-4 bg-black/20 p-3 rounded"><div><label className="block text-xs text-gray-400">Money In</label><input type="number" className="w-full bg-gray-900 border border-gray-600 rounded p-2 text-white" required onChange={e => setForm({...form, moneyIn: e.target.value})} /></div><div><label className="block text-xs text-gray-400">Money Out</label><input type="number" className="w-full bg-gray-900 border border-gray-600 rounded p-2 text-white" required onChange={e => setForm({...form, moneyOut: e.target.value})} /></div></div><div className="flex gap-3 pt-4"><button type="button" onClick={onCancel} className="flex-1 bg-gray-700 py-3 rounded hover:bg-gray-600">Cancel</button><button type="submit" className="flex-1 bg-purple-600 py-3 rounded hover:bg-purple-500 font-bold">Save Log</button></div></form></div>
    );
};
export default MachineLogger;